LIST = {"name": "radar_list", "description": "List scheduler timers (follow-ups) of the current scope.", "parameters": {"type": "object", "additionalProperties": False, "properties": {"limit": {"type": "integer", "minimum": 1, "maximum": 100}}}}
INSPECT = {"name": "radar_inspect", "description": "Inspect one local radar object by id (task, signal, proposal, job, source...). Read-only.", "parameters": {"type": "object", "additionalProperties": False, "required": ["id"], "properties": {"id": {"type": "string"}}}}
PROPOSE = {"name": "radar_propose", "description": "Create an immutable read-only plan for an existing follow-up when policy validates operation, source, resource and grant. Never grants consent nor executes changes.", "parameters": {"type": "object", "additionalProperties": False, "required": ["operation_id", "parameters", "followup_id", "source_id"], "properties": {"operation_id": {"type": "string"}, "parameters": {"type": "object"}, "followup_id": {"type": "string"}, "source_id": {"type": "string"}}}}
TASKS = {"name": "radar_tasks", "description": "List the owner's tracked tasks (trips, purchases, work items, commitments) with their pending proposals. Use it to answer 'what is pending' or before resolving a proposal.", "parameters": {"type": "object", "additionalProperties": False, "properties": {"status": {"type": "string", "enum": ["open", "all", "closed"]}, "limit": {"type": "integer", "minimum": 1, "maximum": 100}}}}
