EXPLAIN = {"name": "radar_explain", "description": "Explain one tracked task: evidence signals, checklist, proposals and jobs. Optionally writes a standalone HTML report and returns its path.", "parameters": {"type": "object", "additionalProperties": False, "required": ["task_id"], "properties": {"task_id": {"type": "string"}, "html": {"type": "boolean"}}}}


def as_json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, default=str)
